/* ---------- Agent tree ---------- */
/* an orchestrator and its sub-agents as a tree: a chevron folds a branch, each row shows its task, status and cost, and a
   branch's cost is its own plus everything under it */
.dm-atr{width:100%;max-width:440px;margin:0 auto;padding:6px}
.dm-atr-h{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 10px 10px}
.dm-atr-ht{display:flex;flex-direction:column;min-width:0}
.dm-atr-ht b{font-weight:500;font-size:14px}
.dm-atr-st{font-size:12.5px}
.dm-atr-tot{font-size:14px;font-weight:500}
.dm-atr-tree{display:flex;flex-direction:column;padding-top:4px;border-top:1px solid var(--dm-line)}
.dm-atr-n{display:flex;align-items:center;gap:8px;min-height:44px;padding:5px 10px 5px calc(4px + var(--dm-lv,0) * 20px);border-radius:10px;font-size:13px;outline:0;transition:background .16s}
.dm-atr-n:hover{background:var(--dm-row)}
.dm-atr-n:focus-visible{box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--dm-accent) 45%,transparent)}
.dm-atr-tg{width:20px;height:20px;display:grid;place-items:center;flex:none;border-radius:6px;color:var(--dm-muted);transition:background .16s,color .16s}
.dm-atr-tg:hover{background:var(--dm-chip);color:var(--dm-fg)}
.dm-atr-tg svg{transition:transform .32s var(--dm-ease)}
.dm-atr-n[aria-expanded="false"] .dm-atr-tg svg{transform:rotate(-90deg)}
.dm-atr-sp{width:20px;flex:none}
.dm-atr-g{width:16px;height:16px;display:grid;place-items:center;flex:none;color:var(--dm-faint)}
.dm-atr-g .dm-spin{width:11px;height:11px;color:var(--dm-accent)}
.dm-atr-n.dm-done .dm-atr-g{color:var(--dm-ok)}
.dm-atr-n.dm-fail .dm-atr-g{color:var(--dm-bad)}
.dm-atr-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-atr-t b{font-weight:500}
.dm-atr-t span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-atr-n.dm-fail .dm-atr-t span{color:var(--dm-bad)}
.dm-atr-n.dm-queued .dm-atr-t b{color:var(--dm-fg2)}
.dm-atr-c{font-size:12.5px;color:var(--dm-fg2);min-width:44px;text-align:right}
.dm-atr-n.dm-queued .dm-atr-c{color:var(--dm-muted)}
/* the way out of a failed step: a white button on its red-tinted row */
.dm-atr-n.dm-fail{background:var(--dm-bad-bg)}
.dm-atr-fix{flex:none;align-self:flex-start;margin-top:4px;background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
.dm-atr-fix:hover{background:var(--dm-surface);box-shadow:var(--dm-shadow-pop)}
/* a folded branch keeps its children's space shut; the guide line marks the level */
.dm-atr-kids{position:relative}
.dm-atr-kids::before{content:"";position:absolute;top:2px;bottom:6px;left:calc(14px + var(--dm-lv,0) * 20px);width:1px;background:var(--dm-line)}
.dm-atr-sum{display:flex;align-items:center;gap:8px;margin:8px 4px 2px;padding:10px 12px;border-radius:12px;background:var(--dm-ok-bg);font-size:13px}
.dm-atr-sum svg{color:var(--dm-ok);flex:none}

